DO $$ BEGIN CREATE TYPE user_status AS ENUM ('active','suspended','banned'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE user_role AS ENUM ('user','admin'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE license_status AS ENUM ('active','paused','revoked','expired'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,max_devices int NOT NULL DEFAULT 1 CHECK(max_devices>0),features jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),username text UNIQUE NOT NULL,password_hash text NOT NULL,role user_role NOT NULL DEFAULT 'user',status user_status NOT NULL DEFAULT 'active',note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS licenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,plan_id uuid NOT NULL REFERENCES plans(id),status license_status NOT NULL DEFAULT 'active',starts_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,fingerprint_hash text NOT NULL,name text NOT NULL,platform text NOT NULL,app_version text NOT NULL,revoked boolean NOT NULL DEFAULT false,first_seen_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,fingerprint_hash));
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,device_id uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE,family_id uuid NOT NULL,jti uuid UNIQUE NOT NULL,token_hash text NOT NULL,consumed_at timestamptz,revoked_at timestamptz,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_family_idx ON sessions(family_id);
CREATE TABLE IF NOT EXISTS releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),version text UNIQUE NOT NULL,minimum_version text NOT NULL,url text NOT NULL,sha256 text NOT NULL,signature text NOT NULL,mandatory boolean NOT NULL DEFAULT false,published_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_user_id uuid REFERENCES users(id),action text NOT NULL,target_type text NOT NULL,target_id text NOT NULL,ip text NOT NULL DEFAULT '',result text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_created_idx ON audit_logs(created_at DESC);
INSERT INTO plans(name,max_devices,features) VALUES ('Basic',1,'["proxy","rules"]'),('Professional',3,'["proxy","rules","custom-lines","priority-support"]') ON CONFLICT(name) DO NOTHING;
